        var errs []error
        for _, p := range pods {
                if apiCacher != nil {
                        // When API cacher is available, use it to clear the NominatedNodeName.
                        _, err := apiCacher.PatchPodStatus(p, nil, &fwk.NominatingInfo{NominatedNodeName: "", NominatingMode: fwk.ModeOverride})
                        if err != nil {
